package com.example.techfix;
import android.content.Intent; import android.os.*; import android.view.View; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity; import androidx.recyclerview.widget.*; import com.example.techfix.data.AppDatabase; import com.example.techfix.data.entity.*; import com.example.techfix.ui.*; import java.util.*; import java.util.concurrent.*;
public class AppointmentsActivity extends AppCompatActivity { private final ExecutorService executor=Executors.newSingleThreadExecutor(); private final Handler main=new Handler(Looper.getMainLooper());
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_appointments);int userId=getIntent().getIntExtra("USER_ID",-1);boolean completed=getIntent().getBooleanExtra("FILTER_COMPLETED",false);TextView title=findViewById(R.id.tvAppointmentsTitle);title.setText(completed?"Repair History":"My Appointments");RecyclerView rv=findViewById(R.id.rvAppointments);rv.setLayoutManager(new LinearLayoutManager(this));TextView empty=findViewById(R.id.tvEmptyState);AppDatabase db=AppDatabase.getDatabase(getApplicationContext());executor.execute(()->{List<Appointment> all=db.appointmentDao().getAppointmentsByCustomer(userId);List<Appointment> filtered=new ArrayList<>();for(Appointment a:all)if(!completed||"Completed".equals(a.getStatus()))filtered.add(a);List<AppointmentDisplay> displays=new ArrayList<>();for(Appointment a:filtered){Branch br=db.branchDao().getBranchById(a.getBranchId());RepairService s=db.repairServiceDao().getServiceById(a.getServiceId());displays.add(new AppointmentDisplay(a.getAppointmentId(),a.getRequestedDate(),br==null?"Unknown Branch":br.getName(),s==null?"Unknown Service":s.getName(),a.getStatus()));}main.post(()->{if(displays.isEmpty()){empty.setVisibility(View.VISIBLE);empty.setText(completed?"No completed repairs yet.":"No appointments yet.");return;}empty.setVisibility(View.GONE);rv.setAdapter(new AppointmentAdapter(displays,a->{Intent i=new Intent(this,AppointmentDetailActivity.class);i.putExtra("APPOINTMENT_ID",a.getAppointmentId());startActivity(i);}));});});}
 @Override protected void onDestroy(){executor.shutdown();super.onDestroy();}
}